package io.github.mightycode.mightylib.graphics.shader;

import io.github.mightycode.mightylib.resources.Resources;
import io.github.mightycode.mightylib.utils.Logger;
import org.joml.Matrix4f;
import org.lwjgl.BufferUtils;

import java.nio.FloatBuffer;

import static org.lwjgl.opengl.GL20.glUniformMatrix4fv;

/**
 * Fallback of the shaders: plain magenta, generated by the code (no file), it can't fail.
 * Its vertex position is a vec4 at location 0: the 2D (vec2) and 3D (vec3) shapes both work with it.
 * The matrices start as identity, so a full screen quad without matrices (post processing) is magenta too.
 */
public class FallbackShader extends Shader {
    private static final String[] MATRICES = {
            ShaderManager.GENERIC_PROJECTION_FIELD_NAME,
            ShaderManager.GENERIC_VIEW_FIELD_NAME,
            ShaderManager.GENERIC_MODEL_FIELD_NAME
    };

    private final boolean modernGLSL;

    // version: folder of the shaders (ShaderManager.getVersion), "3_30" or "1_40"
    public FallbackShader(String version) {
        // No path: nothing is read by the loader
        super(Resources.FALLBACK_NAME, false, null, null);
        modernGLSL = !"1_40".equals(version);
    }

    @Override
    protected boolean internLoad() {
        String header = modernGLSL ? "#version 330 core\nlayout (location = 0) " : "#version 140\n";

        setShaderContent(0, header + "in vec4 aPos;\n"
                + "uniform mat4 projection;\nuniform mat4 view;\nuniform mat4 model;\n"
                + "void main() { gl_Position = projection * view * model * aPos; }\n");
        setShaderContent(1, (modernGLSL ? "#version 330 core\n" : "#version 140\n")
                + "out vec4 fragColor;\n"
                + "void main() { fragColor = vec4(1.0, 0.0, 1.0, 1.0); }\n");

        if (!super.internLoad())
            return false;

        FloatBuffer identity = new Matrix4f().get(BufferUtils.createFloatBuffer(16));
        use();
        for (String matrix : MATRICES) {
            int link = getLink(matrix);
            if (link != -1)
                glUniformMatrix4fv(link, false, identity);
        }
        Logger.CheckOpenGLError("Fallback shader matrices");

        return true;
    }
}
